use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut lefts: Vec<int> = []
    let mut rights: Vec<int> = []
    let mut root: int = -1
    for line in text.lines() {
        let parts: Vec<string> = line.trim().split(" ").collect()
        let cmd = parts[0]
        let mut x: int = 0
        if parts.len() > 1 {
            x = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" {
            let mut cur = root
            let mut par: int = -1
            let mut goleft = false
            let mut found = false
            while cur != -1 {
                if keys[cur] == x {
                    found = true
                    break
                }
                par = cur
                if x < keys[cur] {
                    goleft = true
                    cur = lefts[cur]
                } else {
                    goleft = false
                    cur = rights[cur]
                }
            }
            if found {
                println("dup")
            } else {
                let idx: int = keys.len() as int
                keys.push(x)
                lefts.push(-1)
                rights.push(-1)
                if par == -1 {
                    root = idx
                } else if goleft {
                    lefts[par] = idx
                } else {
                    rights[par] = idx
                }
                println("ok")
            }
        } else if cmd == "contains" {
            let mut cur = root
            let mut found = false
            while cur != -1 {
                if keys[cur] == x {
                    found = true
                    break
                }
                if x < keys[cur] {
                    cur = lefts[cur]
                } else {
                    cur = rights[cur]
                }
            }
            if found { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let mut cur = root
            let mut par: int = -1
            let mut goleft = false
            let mut found = false
            while cur != -1 {
                if keys[cur] == x {
                    found = true
                    break
                }
                par = cur
                if x < keys[cur] {
                    goleft = true
                    cur = lefts[cur]
                } else {
                    goleft = false
                    cur = rights[cur]
                }
            }
            if !found {
                println("missing")
            } else {
                if lefts[cur] != -1 && rights[cur] != -1 {
                    let mut sp = cur
                    let mut s = rights[cur]
                    while lefts[s] != -1 {
                        sp = s
                        s = lefts[s]
                    }
                    keys[cur] = keys[s]
                    if sp == cur {
                        rights[sp] = rights[s]
                    } else {
                        lefts[sp] = rights[s]
                    }
                } else {
                    let mut child = lefts[cur]
                    if child == -1 {
                        child = rights[cur]
                    }
                    if par == -1 {
                        root = child
                    } else if goleft {
                        lefts[par] = child
                    } else {
                        rights[par] = child
                    }
                }
                println("ok")
            }
        } else if cmd == "inorder" {
            let mut out: Vec<string> = []
            let mut stack: Vec<int> = []
            let mut cur = root
            while cur != -1 || stack.len() > 0 {
                while cur != -1 {
                    stack.push(cur)
                    cur = lefts[cur]
                }
                let n = stack.pop().unwrap_or(0)
                out.push("${keys[n]}")
                cur = rights[n]
            }
            if out.len() == 0 {
                println("<empty>")
            } else {
                println(out.join(" "))
            }
        } else if cmd == "height" {
            let mut best: int = 0
            let mut stack: Vec<int> = []
            let mut depths: Vec<int> = []
            if root != -1 {
                stack.push(root)
                depths.push(1)
            }
            while stack.len() > 0 {
                let n = stack.pop().unwrap_or(0)
                let d = depths.pop().unwrap_or(0)
                if d > best { best = d }
                if lefts[n] != -1 {
                    stack.push(lefts[n])
                    depths.push(d + 1)
                }
                if rights[n] != -1 {
                    stack.push(rights[n])
                    depths.push(d + 1)
                }
            }
            println("${best}")
        } else if cmd == "min" {
            if root == -1 {
                println("empty")
            } else {
                let mut cur = root
                while lefts[cur] != -1 { cur = lefts[cur] }
                println("${keys[cur]}")
            }
        } else if cmd == "max" {
            if root == -1 {
                println("empty")
            } else {
                let mut cur = root
                while rights[cur] != -1 { cur = rights[cur] }
                println("${keys[cur]}")
            }
        }
    }
}

